def _active_managers(hass: HomeAssistant) -> list[ReminderManager]:
    """Persons that are loaded or currently being set up (not unloading)."""
    return [
        entry.runtime_data
        for entry in hass.config_entries.async_entries(DOMAIN)
        if entry.state in (ConfigEntryState.LOADED, ConfigEntryState.SETUP_IN_PROGRESS)
        and isinstance(getattr(entry, "runtime_data", None), ReminderManager)
    ]


def _texts(hass: HomeAssistant) -> dict[str, str]:
    language = (hass.config.language or "en").split("-")[0]
    return TEXTS.get(language, TEXTS["en"])


def _press(entity_id: str, confirmation: str | None = None) -> dict[str, Any]:
    action: dict[str, Any] = {
        "action": "perform-action",
        "perform_action": "button.press",
        "target": {"entity_id": entity_id},
    }
    if confirmation:
        action["confirmation"] = {"text": confirmation}
    return action


def _state_is(entity_id: str, state: str) -> list[dict[str, Any]]:
    return [{"condition": "state", "entity": entity_id, "state": state}]


def _gauge(entity_id: str, name: str) -> dict[str, Any]:
    return {
        "type": "gauge",
        "entity": entity_id,
        "name": name,
        "min": 0,
        "max": 100,
        "needle": True,
        "severity": {"green": 90, "yellow": 70, "red": 0},
        "grid_options": {"columns": 6},
    }


class _Ids:
    """Look up entity ids by unique id (robust against renames and language)."""

    def __init__(self, hass: HomeAssistant) -> None:
        self._registry = er.async_get(hass)

    def get(self, domain: str, unique_id: str) -> str | None:
        return self._registry.async_get_entity_id(domain, DOMAIN, unique_id)


def _medication_cards(
    ids: _Ids, manager: ReminderManager, texts: dict[str, str]
) -> tuple[list[dict], list[dict], list[dict], list[str], list[str]]:
    """Cards per medication: (take now, today, per-medication entities, charts, logbook)."""
    now_cards: list[dict] = []
    today_cards: list[dict] = []
    stats_rows: list[dict] = []
    chart_ids: list[str] = []
    status_ids: list[str] = []

    for med in sorted(manager.medications.values(), key=lambda m: m.name.lower()):
        uid = med.id
        due = ids.get("binary_sensor", f"{uid}_due")
        taken = ids.get("button", f"{uid}_taken")
        snooze = ids.get("button", f"{uid}_snooze")
        skip = ids.get("button", f"{uid}_skip")
        status = ids.get("sensor", f"{uid}_status")
        next_dose = ids.get("sensor", f"{uid}_next_dose")
        last_taken = ids.get("sensor", f"{uid}_last_taken")
        adherence_7 = ids.get("sensor", f"{uid}_adherence_7d")
        adherence_30 = ids.get("sensor", f"{uid}_adherence_30d")
        streak = ids.get("sensor", f"{uid}_streak")
        reminders = ids.get("switch", f"{uid}_reminders")
        title = f"{med.name} {med.dosage}".strip()

        if due and taken:
            now_cards.append(
                {
                    "type": "tile",
                    "entity": taken,
                    "name": f"{title} {texts['taken']}",
                    "icon": "mdi:check-circle",
                    "color": "green",
                    "hide_state": True,
                    "tap_action": _press(taken),
                    "grid_options": {"columns": 8},
                    "visibility": _state_is(due, "on"),
                }
            )
        if due and snooze:
            now_cards.append(
                {
                    "type": "tile",
                    "entity": snooze,
                    "name": texts["later"],
                    "icon": "mdi:alarm-snooze",
                    "color": "amber",
                    "hide_state": True,
                    "tap_action": _press(snooze),
                    "grid_options": {"columns": 4},
                    "visibility": _state_is(due, "on"),
                }
            )

        if status:
            today_cards.append(
                {
                    "type": "tile",
                    "entity": status,
                    "name": title,
                    "icon": "mdi:pill",
                    "grid_options": {"columns": 6},
                }
            )
            status_ids.append(status)
        if next_dose:
            today_cards.append(
                {
                    "type": "tile",
                    "entity": next_dose,
                    "name": texts["next"],
                    "grid_options": {"columns": 6},
                }
            )
        if taken:
            today_cards.append(
                {
                    "type": "tile",
                    "entity": taken,
                    "name": texts["taken"].capitalize(),
                    "color": "green",
                    "hide_state": True,
                    "tap_action": _press(taken, texts["confirm_taken"].format(name=med.name)),
                    "grid_options": {"columns": 4},
                }
            )
        if skip:
            today_cards.append(
                {
                    "type": "tile",
                    "entity": skip,
                    "name": texts["skip"],
                    "color": "grey",
                    "hide_state": True,
                    "tap_action": _press(skip, texts["confirm_skip"].format(name=med.name)),
                    "grid_options": {"columns": 4},
                }
            )
        if reminders:
            today_cards.append(
                {
                    "type": "tile",
                    "entity": reminders,
                    "name": texts["remind"],
                    "grid_options": {"columns": 4},
                }
            )

        for entity_id, label in (
            (adherence_7, texts["days_7"]),
            (adherence_30, texts["days_30"]),
            (streak, None),  # entity name is already "<medication> Serie"
            (last_taken, None),
        ):
            if entity_id:
                row: dict[str, Any] = {"entity": entity_id}
                if label:
                    row["name"] = f"{med.name} · {label}"
                stats_rows.append(row)
        if adherence_7:
            chart_ids.append(adherence_7)

    return now_cards, today_cards, stats_rows, chart_ids, status_ids


def _manage_cards(ids: _Ids, manager: ReminderManager, texts: dict[str, str]) -> list[dict]:
    """Cards to edit, add and delete medications."""
    cards: list[dict[str, Any]] = [
        {"type": "heading", "heading": texts["manage"], "icon": "mdi:cog"},
        {"type": "markdown", "content": texts["manage_hint"]},
    ]
    for med in sorted(manager.medications.values(), key=lambda m: m.name.lower()):
        rows: list[Any] = [
            entity_id
            for entity_id in (
                ids.get("text", f"{med.id}_cfg_name"),
                ids.get("text", f"{med.id}_cfg_times"),
                ids.get("text", f"{med.id}_cfg_weekdays"),
                ids.get("text", f"{med.id}_cfg_dosage"),
                ids.get("number", f"{med.id}_cfg_early_minutes"),
                ids.get("number", f"{med.id}_cfg_late_minutes"),
                ids.get("switch", f"{med.id}_reminders"),
            )
            if entity_id
        ]
        if delete := ids.get("button", f"{med.id}_delete_medication"):
            rows.append(
                {
                    "type": "button",
                    "name": texts["delete"],
                    "icon": "mdi:delete",
                    "action_name": texts["delete"],
                    "tap_action": _press(delete, texts["confirm_delete"].format(name=med.name)),
                }
            )
        cards.append(
            {
                "type": "entities",
                "title": med.name,
                "state_color": True,
                "entities": rows,
                "grid_options": {"columns": 6},
            }
        )

    eid = manager.entry_id
    new_rows: list[Any] = [
        entity_id
        for entity_id in (
            ids.get("text", f"{eid}_new_name"),
            ids.get("text", f"{eid}_new_times"),
            ids.get("text", f"{eid}_new_dosage"),
        )
        if entity_id
    ]
    if add := ids.get("button", f"{eid}_add_medication"):
        new_rows.append(
            {
                "type": "button",
                "name": texts["new_medication"],
                "icon": "mdi:plus-circle",
                "action_name": texts["add"],
                "tap_action": _press(add, texts["confirm_add"]),
            }
        )
    cards.append(
        {
            "type": "entities",
            "title": texts["new_medication"],
            "entities": new_rows,
            "grid_options": {"columns": 6},
        }
    )
    return cards


def _person_view(
    hass: HomeAssistant,
    ids: _Ids,
    manager: ReminderManager,
    texts: dict[str, str],
    admin_ids: list[str],
    path: str,
) -> dict[str, Any]:
    eid = manager.entry_id
    any_due = ids.get("binary_sensor", f"{eid}_any_due")
    open_today = ids.get("sensor", f"{eid}_open_today")
    taken_today = ids.get("sensor", f"{eid}_taken_today")
    missed_today = ids.get("sensor", f"{eid}_missed_today")
    skipped_today = ids.get("sensor", f"{eid}_skipped_today")
    adherence_7 = ids.get("sensor", f"{eid}_adherence_7d")
    adherence_30 = ids.get("sensor", f"{eid}_adherence_30d")
    calendar = ids.get("calendar", f"{eid}_doses")

    now_cards, today_cards, stats_rows, chart_ids, status_ids = _medication_cards(
        ids, manager, texts
    )
    sections: list[dict[str, Any]] = []

    # 1) Take now - only while something is due
    if any_due and now_cards:
        sections.append(
            {
                "type": "grid",
                "visibility": _state_is(any_due, "on"),
                "cards": [
                    {"type": "heading", "heading": texts["now"], "icon": "mdi:bell-ring"},
                    *now_cards,
                ],
            }
        )

    # 2) Today
    today: list[dict[str, Any]] = [
        {"type": "heading", "heading": texts["today"], "icon": "mdi:calendar-today"}
    ]
    if not manager.medications:
        today.append({"type": "markdown", "content": texts["no_medication"]})
    elif any_due:
        today.append(
            {
                "type": "markdown",
                "content": texts["nothing_due"],
                "visibility": _state_is(any_due, "off"),
            }
        )
    today.extend(today_cards)
    sections.append({"type": "grid", "cards": today})

    # 3) Summary
    summary: list[dict[str, Any]] = [
        {"type": "heading", "heading": texts["balance"], "icon": "mdi:chart-arc"}
    ]
    for entity_id, color in (
        (taken_today, "green"),
        (missed_today, "red"),
        (skipped_today, "grey"),
    ):
        if entity_id:
            summary.append(
                {
                    "type": "tile",
                    "entity": entity_id,
                    "color": color,
                    "grid_options": {"columns": 4},
                }
            )
    if adherence_7:
        summary.append(_gauge(adherence_7, texts["days_7"]))
    if adherence_30:
        summary.append(_gauge(adherence_30, texts["days_30"]))
    if stats_rows:
        summary.append(
            {"type": "entities", "title": texts["per_medication"], "entities": stats_rows}
        )
    sections.append({"type": "grid", "cards": summary})

    # 4) History
    history: list[dict[str, Any]] = [
        {"type": "heading", "heading": texts["history"], "icon": "mdi:chart-line"}
    ]
    chart_entities = ([{"entity": adherence_7, "name": texts["total"]}] if adherence_7 else []) + [
        {"entity": entity_id} for entity_id in chart_ids
    ]
    if chart_entities:
        history.append(
            {
                "type": "statistics-graph",
                "title": texts["adherence_chart"],
                "chart_type": "line",
                "period": "day",
                "days_to_show": 30,
                "stat_types": ["mean"],
                "entities": chart_entities,
                "grid_options": {"columns": "full"},
            }
        )
    if status_ids:
        history.append(
            {
                "type": "history-graph",
                "title": texts["status_chart"],
                "hours_to_show": 168,
                "entities": status_ids,
                "grid_options": {"columns": "full"},
            }
        )
    if len(history) > 1:
        sections.append({"type": "grid", "column_span": 2, "cards": history})

    # 5) Calendar
    if calendar:
        sections.append(
            {
                "type": "grid",
                "column_span": 3,
                "cards": [
                    {"type": "heading", "heading": texts["calendar"], "icon": "mdi:calendar-check"},
                    {
                        "type": "calendar",
                        "initial_view": "listWeek",
                        "entities": [calendar],
                        "grid_options": {"columns": "full"},
                    },
                ],
            }
        )

    # 6) Log
    if status_ids:
        sections.append(
            {
                "type": "grid",
                "column_span": 3,
                "cards": [
                    {
                        "type": "heading",
                        "heading": texts["log"],
                        "icon": "mdi:format-list-bulleted",
                    },
                    {
                        "type": "logbook",
                        "hours_to_show": 168,
                        "target": {"entity_id": status_ids},
                        "grid_options": {"columns": "full"},
                    },
                ],
            }
        )

    view: dict[str, Any] = {
        "title": manager.person,
        "path": path,
        "icon": DASHBOARD_ICON,
        "type": "sections",
        "max_columns": 3,
        "badges": [
            {"type": "entity", "entity": entity_id, "show_name": True}
            for entity_id in (open_today, taken_today, missed_today, adherence_7)
            if entity_id
        ],
        "sections": sections,
    }
    _restrict(view, manager, admin_ids)
    return view


def _restrict(view: dict[str, Any], manager: ReminderManager, admin_ids: list[str]) -> None:
    """Only the person's own user and administrators see a view."""
    visible_users = list(dict.fromkeys([u for u in [manager.user_id, *admin_ids] if u]))
    if visible_users:
        view["visible"] = [{"user": user_id} for user_id in visible_users]


def _manage_view(
    ids: _Ids,
    manager: ReminderManager,
    texts: dict[str, str],
    admin_ids: list[str],
    path: str,
    title: str,
) -> dict[str, Any]:
    """Separate tab to add, edit and delete medications."""
    view: dict[str, Any] = {
        "title": title,
        "path": path,
        "icon": "mdi:pill-multiple",
        "type": "sections",
        "max_columns": 3,
        "sections": [
            {"type": "grid", "column_span": 3, "cards": _manage_cards(ids, manager, texts)}
        ],
    }
    _restrict(view, manager, admin_ids)
    return view


async def async_build_dashboard(hass: HomeAssistant) -> dict[str, Any]:
    """Build the dashboard config for all loaded persons."""
    texts = _texts(hass)
    ids = _Ids(hass)
    users = await hass.auth.async_get_users()
    admin_ids = [u.id for u in users if u.is_admin and u.is_active and not u.system_generated]

    managers = sorted(_active_managers(hass), key=lambda m: m.person.lower())
    views: list[dict[str, Any]] = []
    used_paths: set[str] = set()
    for manager in managers:
        path = slugify(manager.person) or manager.entry_id.lower()
        if path in used_paths:
            path = f"{path}-{manager.entry_id[-6:].lower()}"
        used_paths.add(path)
        views.append(_person_view(hass, ids, manager, texts, admin_ids, path))
        # With several persons the tab name says whose medication it is.
        manage_title = (
            texts["manage"] if len(managers) == 1 else f"{texts['manage']} ({manager.person})"
        )
        views.append(
            _manage_view(
                ids, manager, texts, admin_ids, f"{path}-{texts['manage_path']}", manage_title
            )
        )

    if not views:
        views.append(
            {
                "title": texts["title"],
                "path": "start",
                "cards": [{"type": "markdown", "content": texts["no_person"]}],
            }
        )
    return {"title": texts["title"], "views": views}


class PillReminderDashboard(LovelaceConfig):
    """Read-only dashboard whose config is generated on every load."""

    def __init__(self, hass: HomeAssistant, title: str) -> None:
        """Initialize."""
        super().__init__(
            hass,
            DASHBOARD_URL,
            {
                "mode": "yaml",
                "title": title,
                "icon": DASHBOARD_ICON,
                "show_in_sidebar": True,
                "require_admin": False,
            },
        )

    @property
    def mode(self) -> str:
        """Generated dashboards cannot be edited in the UI."""
        return "yaml"

    async def async_get_info(self) -> dict[str, Any]:
        """Return the config info."""
        config = await self.async_load(False)
        return {"mode": self.mode, "views": len(config["views"])}

    async def async_load(self, force: bool) -> dict[str, Any]:
        """Generate the config."""
        return await async_build_dashboard(self.hass)

    async def async_json(self, force: bool) -> json_fragment:
        """Return the generated config as JSON."""
        return json_fragment(json_bytes(await self.async_load(force)))

    @callback
    def async_notify_changed(self) -> None:
        """Tell open browsers to reload the dashboard."""
        self._config_updated()


@callback
def async_update_dashboard(hass: HomeAssistant, *, removed_entry_id: str | None = None) -> None:
    """Register or refresh the dashboard; remove it when the last person is deleted.

    Unloading (e.g. a reload after adding a medication) only refreshes the
    dashboard, so it does not briefly disappear from the sidebar.
    """
    lovelace = hass.data.get(LOVELACE_DATA)
    if lovelace is None or "frontend" not in hass.config.components:
        _LOGGER.debug("Lovelace not loaded, no dashboard created")
        return

    existing = lovelace.dashboards.get(DASHBOARD_URL)

    if existing is not None and not isinstance(existing, PillReminderDashboard):
        _LOGGER.warning(
            "A dashboard with the URL /%s already exists; the Pill Reminder "
            "dashboard is not created",
            DASHBOARD_URL,
        )
        return

    if existing is not None:
        remaining = [
            e for e in hass.config_entries.async_entries(DOMAIN) if e.entry_id != removed_entry_id
        ]
        if not remaining:
            frontend.async_remove_panel(hass, DASHBOARD_URL, warn_if_unknown=False)
            lovelace.dashboards.pop(DASHBOARD_URL, None)
            return
        existing.async_notify_changed()
        return

    if not _active_managers(hass):
        return

    title = _texts(hass)["title"]
    lovelace.dashboards[DASHBOARD_URL] = PillReminderDashboard(hass, title)
    frontend.async_register_built_in_panel(
        hass,
        "lovelace",
        sidebar_title=title,
        sidebar_icon=DASHBOARD_ICON,
        frontend_url_path=DASHBOARD_URL,
        config={"mode": "yaml"},
        require_admin=False,
    )
